from __future__ import annotations

from typing import Any


class Action:
    action_type = "action"

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
        }


class SetStateAction(Action):
    action_type = "set_state"

    def __init__(self, key: str, value: Any):
        self.key = key
        self.value = value

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
            "key": self.key,
            "value": self.value,
        }


class IncrementStateAction(Action):
    action_type = "increment_state"

    def __init__(self, key: str, amount: int | float = 1):
        self.key = key
        self.amount = amount

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
            "key": self.key,
            "amount": self.amount,
        }


class RunFunctionAction(Action):
    action_type = "run_function"

    def __init__(self, name: str, payload: dict[str, Any] | None = None):
        self.name = name
        self.payload = payload or {}

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
            "name": self.name,
            "payload": self.payload,
        }


class NavigateAction(Action):
    action_type = "navigate"

    def __init__(self, href: str):
        self.href = href

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": self.action_type,
            "href": self.href,
        }
